        					continue;
			}
			args[arg][j] = args[arg][i];
			j++;
		}
		args[arg][j] = '\0';
		arg++;
	}

	appctx->ctx.stats.scope_str = 0;
	appctx->ctx.stats.scope_len = 0;
	appctx->ctx.stats.flags = 0;
	appctx->st2 = 0;

	kw = cli_find_kw(args);
	if (!kw || !kw->parse)
		return 0;

	appctx->io_handler = kw->io_handler;
	if (kw->parse(args, appctx, kw->private) == 0 && appctx->io_handler) {
